mapper.select:
SELECT c.id, c.content, c.status, c.created_at as createdAt, c.target_type as targetType, c.target_id as targetId, u.id as userId, u.nickname as userName, u.avatar as userAvatar FROM comments c LEFT JOIN users u ON c.user_id = u.id WHERE 1=1
AND c.status = #{status}
ORDER BY c.created_at DESC LIMIT #{offset}, #{size}

SELECT r.id, r.content, r.status, r.created_at as createdAt, r.comment_id as commentId, u.id as userId, u.nickname as userName, u.avatar as userAvatar FROM replies r LEFT JOIN users u ON r.user_id = u.id WHERE 1=1
AND r.status = #{status}
ORDER BY r.created_at DESC LIMIT #{offset}, #{size}
